import type { TutorialLevel } from './TutorialCard'

/**
 * Every icon in this app, in one place — extracted (per the user's own ask,
 * once Storybook made "these are scattered across six files" obvious) from
 * wherever each one used to live as a private helper right next to its one
 * call site: AccountScreen.tsx, HomeScreen.tsx, InfoOverlay.tsx,
 * MyProductsScreen.tsx, ScreenHeader.tsx, TutorialCard.tsx. Each icon's own
 * doc comment (source asset, viewBox/opacity reasoning, revision history)
 * moved with it rather than being dropped — see each one below for the
 * "why," not just the "what." Two were already exported for cross-file
 * reuse before this move (CloseIcon, the toggle BookmarkIcon); every other
 * one was genuinely private until now.
 *
 * One real naming collision surfaced doing this: AccountScreen.tsx had its
 * own unrelated `BookmarkIcon()` (a plain 16x16 menu-row glyph, fi-br-
 * bookmark) that happened to share a name with TutorialCard.tsx's real
 * toggle-state bookmark icon (`BookmarkIcon({ filled })`, 22x24, save/unsave
 * a look) — two different icons, never actually the same shape, that could
 * coexist as same-named private helpers in two different files but not as
 * two exports from one shared one. Renamed the menu-row glyph to
 * `BookmarkGlyphIcon`; the toggle icon keeps the shorter, more central name
 * since BookmarksScreen.tsx already imports it by that name.
 */

// --- Account screen (AccountScreen.tsx) ---------------------------------
// Figma: node 749:10533 ("Home/Profile"), file Tech-Experimentation. Hand-
// authored inline SVGs with real path data pulled from that node's exported
// assets (fi-br-box/-bookmark/-calculator/-angle-small-right), same
// convention as every other icon in this app — `fill="currentColor"`,
// color supplied by the call site (ROW_ICON_STYLE/wrapping span in
// AccountScreen.tsx), rather than a raw `<img src>` of the remote asset,
// which would also expire in ~7 days.
//
// Verify pass (2026-09-01): all four used to carry a baked `fillOpacity`
// (0.8 on the row icons, 0.5 on the chevron) on top of an already-opaque
// `color` from the call site — the same residual-opacity bug already fixed
// on CloseIcon/PlusIcon/MenuDotsIcon elsewhere in this file. Downloading
// the raw fi-br-box/-bookmark/-calculator assets Figma serves confirms a
// flat #656462 fill (no opacity), and fi-br-angle-small-right confirms a
// flat #CFCECC fill — neither is an alpha-reduced ink color. fillOpacity
// removed from all four; AccountScreen.tsx now supplies --color-info-
// overlay-heading (row icons) / --color-chevron-icon (chevron) as `color`.

